        // Caller must explicitly choose Apply; no startup seed or migrations are registered here.
        public static int Apply(ApplicationDbContext db)
        {
            var catalog = db.Database.Connection.Database;
            if (!catalog.StartsWith("OnlineSalesDemo_", StringComparison.Ordinal) && !catalog.StartsWith("Dacn05_Test_", StringComparison.Ordinal))
                throw new InvalidOperationException("Apply chỉ được phép trên database DEMO/test riêng. Database thật cần được duyệt Preview và quy trình riêng.");
            using (var tx = db.Database.BeginTransaction(IsolationLevel.Serializable))
            {
                var categories = db.Categories.ToList();
                var skus = new HashSet<string>(db.Products.Select(p => p.Sku).ToList().Select(s => s.Trim()), StringComparer.OrdinalIgnoreCase);
                int added = 0;
                foreach (var product in Products())
                {
                    if (skus.Contains(product.Sku)) continue;
                    var category = categories.FirstOrDefault(c => string.Equals(c.Name.Trim(), product.Category.Name, StringComparison.OrdinalIgnoreCase));
                    if (category == null) { category = product.Category; db.Categories.Add(category); categories.Add(category); }
                    product.Category = category;
                    db.Products.Add(product); skus.Add(product.Sku); added++;
                }
                db.SaveChanges(); tx.Commit(); return added;
            }
        }
    }
